function houseSeats(row) {
    return row.id === "DC" ? 0 : row.electoralVotes - 2;
}
export const worldStates = ROWS.map((row) => State.parse({
    id: row.id,
    name: row.name,
    fips: row.fips,
    electoralVotes: row.electoralVotes,
    houseSeats: houseSeats(row),
    // Mass and output live in their own table rather than inline: they are the
    // two columns that get re-based against a new Census or BEA vintage, and a
    // vintage refresh should be a diff of one file rather than 51 edits
    // threaded through the cohort distributions beside them.
    population: STATE_FIGURES[row.id].population,
    grp: STATE_FIGURES[row.id].grp,
    lean: row.lean,
    region: row.region,
    // The vital anchors live in their own table beside the mass figures, for
    // the same reason those do: they are a column that gets re-based together
    // against a new BLS or BEA vintage, and each one is only meaningful
    // against the other fifty, since the three columns are centered on the
    // country as a whole.
    character: {
        ...row.character,
        // The first five axes are authored in the rows above; the other five are the Census-based table.
        cohorts: { ...row.character.cohorts, ...STATE_DEMOGRAPHICS[row.id] },
        vitalAnchor: STATE_VITAL_ANCHORS[row.id],
    },
}));
export const stateById = new Map(worldStates.map((state) => [state.id, state]));
export const ELECTORAL_COLLEGE = 538;
